      "inventory_ordinary": 10000,
      "vehicles_furniture_gain": 0,
      "equipment_section_1245_ordinary": 410000,
      "noncompete_class_vi_ordinary": 400000,
      "goodwill_class_vii_capital": 1610000,
      "big_taken_into_account": { "equipment": 230000, "class_vi_limited_to_recognized_gain": 400000, "total": 630000 },
      "entity_1374_tax": "630000 x 21% = 132300",
      "shareholder_tax": "0.37 x (1,020,000 - 132,300) + 0.20 x 1,610,000 = 328,449 + 322,000 = 650,449"
    }
  },
