      "note_interest_ordinary": "6% on declining balance: 30,000 + 24,000 + 18,000 + 12,000 + 6,000 = 90,000 interest, taxed at 37% = 33,300.",
      "total_tax": "486,000 + 33,300 = 519,300",
      "nominal_net": "2,850,000 + 90,000 interest - 519,300 = 2,420,700"
    },
    "timing_pv": {
      "after_tax_cash_flows": [1949263.16, 101847.37, 98067.37, 94287.37, 90507.37, 86727.37],
      "pv_at_6_percent": 2348288.73,
      "note": "500,000 of the price arrives over 5 years; at a 6% time-value discount the deal is worth about 2,348,289 in closing-day dollars."
    }
  },
  "ray_naive_estimate": {
    "ordinary_income": 0,
    "capital_gain": 3100000,
    "entity_level_tax": 0,
    "total_tax": 620000,
    "net_after_tax": 2480000,
    "why_wrong": "Ray applied 20% to the entire 3,100,000 price. It ignores (1) $620,000 of zero-or-low-basis ordinary items — receivables, inventory margin, and $410,000 of equipment depreciation recapture; (2) the Buyer A draft's $400,000 non-compete priced at ordinary rates; (3) a potential entity-level section 1374 tax because closing falls inside the 2023-2027 recognition period; (4) Buyer B's note is only 2,850,000 and 500,000 of it is paid over five years; and (5) he taxed the gross price rather than the gain over his $420,000 stock basis."
  },
  "comparison": {
    "headline": "If Buyer A accepts the counter allocation, A nets 2,407,941 at closing vs B's 2,420,700 nominal (2,348,289 in 6% present value) — B edges A on nominal dollars, A wins on present value. If Buyer A holds to Exhibit A, B wins under every view.",
    "counter_vs_drafted_delta": 90690,
    "counter_pv_minus_b_pv_at_6": 59652.27,
    "drafted_pv_minus_b_pv_at_6": -31037.73,
    "breakevens": {
      "B_price_matching_counter_A_net_at_6pct_pv": 2924491.42,
      "A_counter_price_matching_B_pv_at_6": 3025434.66,
      "A_drafted_price_matching_B_pv_at_6": 3138797.16
    },
    "b_pv_sensitivity": { "at_6pct": 2348288.73, "at_8pct": 2328042.4, "at_10pct": 2309407.2, "at_12pct": 2292219.41, "at_15pct": 2268841.29 }
  },
  "sensitivities": {
    "accrual_method_AR": {
      "note": "If AR was carried on the accrual method (basis $200,000), AR is zero gain but carries $200,000 of BIG per the conversion appraisal.",
      "drafted_total_tax": 735209, "drafted_net": 2364791,
      "counter_total_tax": 644519, "counter_net": 2455481
    },
    "goodwill_carries_900k_BIG": {
      "note": "If the appraisal's $900,000 goodwill row is independent BIG (not the same 900k reallocated to Class VI), entity tax rises ~$189,000 in both A scenarios and B overtakes even counter-A.",
      "drafted_total_tax": 901819, "drafted_net": 2198181,
      "counter_total_tax": 811129, "counter_net": 2288871
    },
    "assumed_trade_payables": {
      "note": "If Buyer A assumes P of payables, A's net falls by about 0.80P (price stays 3.1M but P of value transfers; modeled as reducing net consideration). At P=200,000 counter-A net falls about 160,000-200,000 depending on drafting; QUESTIONS.md Q2."
    }
  }
}

